def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")


for path, content in NEW_FILES.items():
    write(path, content)

for path, old, new in EXACT_REPLACEMENTS:
    content = read(path)
    count = content.count(old)
    if count != 1:
        raise RuntimeError(
            f"{path}: expected one exact replacement, found {count}"
        )
    write(path, content.replace(old, new, 1))

for path, pattern, replacement, flags in REGEX_REPLACEMENTS:
    content = read(path)
    updated, count = re.subn(
        pattern,
        replacement,
        content,
        count=1,
        flags=flags,
    )
    if count != 1:
        raise RuntimeError(
            f"{path}: expected one regex replacement, found {count}"
        )
    write(path, updated)

print("materialized typed process-edge authority implementation")
